    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(address descriptionHolder) public {
        require(c.jojoTeam() != address(this));
        bool reverted = false;
        c.newEmergencyOracle("any description"); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

