pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _test(address descriptionHolder) internal {
        vm.assume(c.jojoTeam() != address(this));
        bool reverted = false;
        try c.newEmergencyOracle("any description") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_test(address descriptionHolder) public {
        vm.assume(descriptionHolder.code.length == 0 && uint160(descriptionHolder) > 0xffff && descriptionHolder != address(this) && descriptionHolder != address(c) && descriptionHolder != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && descriptionHolder != 0x000000000000000000636F6e736F6c652e6c6f67 && descriptionHolder != 0x4e59b44847b379578588920cA78FbF26c0B4956C && descriptionHolder != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(descriptionHolder);
    }

    receive() external payable {}

    fallback() external payable {}
}
